query GeUnreadMessageCounts($input: GetUnreadCountRequest!) {
  messageApi {
    getUnreadCount(input: $input) {
      count
    }
  }
}

query SalesOverviewByTime($params: DateRangeWithPrecisionVendorsReportRequest!) {
  salesOverview {
    salesByTime(input: $params) {
      order_count
      revenue
      details {
        order_count
        revenue
        milestone
        __typename
      }
      __typename
    }
    __typename
  }
}

query OpsHealth($params: VendorsReportRequest!) {
  reports {
    operationsHealthMetric(input: $params) {
      avgPreparationTime {
        current
        previous
        isGrowthPositive
        dataType
        __typename
      }
      delayRate {
        current
        previous
        isGrowthPositive
        dataType
        __typename
      }
      rejections {
        current
        previous
        isGrowthPositive
        dataType
        __typename
      }
      offlineDuration {
        current
        previous
        isGrowthPositive
        dataType
        __typename
      }
      scheduledDuration {
        current
        previous
        isGrowthPositive
        dataType
        __typename
      }
      __typename
    }
    __typename
  }
}

query LatestReviews($reviewVars: BatchReviewsRequest!, $ratingVars: GetAvgCustomerRatingRequest!, $withAvgRating: Boolean!) {
  customerReview {
    reviews(input: $reviewVars) {
      maxRating
      reviews {
        date
        globalVendorCode
        id
        rating
        text
        vendorPills
        __typename
      }
      __typename
    }
    ratings(input: $ratingVars) @include(if: $withAvgRating) {
      avgRatings {
        avgRating
        maxAllowedRating
        __typename
      }
      __typename
    }
    __typename
  }
}

query TodayIssues($cancelledOrdersCountParams: OrdersCountReq!, $delayedOrdersCountParams: OrdersCountReq!, $issuesMetricParams: DateRangeVendorsMetricRequest!) {
  orders {
    cancelledOrders: ordersCount(input: $cancelledOrdersCountParams) {
      amount
      __typename
    }
    delayedOrders: ordersCount(input: $delayedOrdersCountParams) {
      amount
      __typename
    }
    __typename
  }
  reports {
    issuesMetric(input: $issuesMetricParams) {
      oneStarRatingsCount
      oneStarRatingsDetails {
        global_vendor_code
        count
        __typename
      }
      __typename
    }
    __typename
  }
}

query MenuQuality($params: MenuQualityScoreReportRequest!) {
  reports {
    menuQualityScore(input: $params) {
      data {
        global_vendor_codes
        date
        mqs
        items
        images
        descriptions
        optimalValues {
          items
          images
          descriptions
          __typename
        }
        action
        status
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetRecommendations($input: RecommendationsReq!) {
  recommendations(input: $input) {
